        function link_plot(point1,point2,r,control)
        temp=point2-point1;
        if (~temp(1))&&(~temp(2))
               return;
        end
        theta=cart2pol(temp(1),temp(2));
        [point1_x,point1_y]=pol2cart(theta,r);
        point_1=[point1_x,point1_y]+point1;
